//! Filesystem path admission for received files.
//!
//! The VOT manifest layer already rejects traversal (no "/", "\", ".", "..",
//! control characters, trailing dots). These checks are defense in depth plus
//! votport policy (hidden files off by default), applied before any path
//! touches the disk.

use std::path::{Path, PathBuf};

/// Drops group/other write bits on a directory files are received into. VOT
/// stages next to the destination and refuses a group-writable parent, so a
/// mount created 0775 (umask 002 hosts) would fail every upload into it.
pub fn tighten_dir(path: &Path) {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        if let Ok(meta) = std::fs::metadata(path) {
            let mode = meta.permissions().mode() & 0o7777;
            if mode & 0o022 != 0 {
                let _ =
                    std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode & !0o022));
            }
        }
    }
    #[cfg(not(unix))]
    let _ = path;
}

/// Validates one package path component for on-disk placement.
pub fn admit_component(component: &str, allow_hidden: bool) -> Result<(), String> {
    if component.is_empty() || component.len() > 255 {
        return Err("empty or oversized path component".to_owned());
    }
    if component == "." || component == ".." {
        return Err("path component is a directory reference".to_owned());
    }
    if component
        .chars()
        .any(|ch| ch == '/' || ch == '\\' || ch == '\0' || ch <= '\u{1f}')
    {
        return Err("path component contains a separator or control character".to_owned());
    }
    if !allow_hidden && component.starts_with('.') {
        return Err(
            "hidden file names are not accepted (VOTPORT_ALLOW_HIDDEN=1 to allow)".to_owned(),
        );
    }
    Ok(())
}

/// Validates a link destination subdirectory ("" allowed) and returns its
/// normalized relative form.
pub fn admit_dest(dest: &str) -> Result<String, String> {
    let trimmed = dest.trim().trim_matches('/');
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    let mut parts = Vec::new();
    for component in trimmed.split('/') {
        let component = component.trim();
        if component.is_empty() || component == "." || component == ".." {
            return Err(
                "destination folder may not contain empty, '.' or '..' segments".to_owned(),
            );
        }
        if component.len() > 128
            || !component
                .chars()
                .all(|ch| ch.is_alphanumeric() || matches!(ch, '-' | '_' | '.' | ' '))
            || component.starts_with('.')
        {
            return Err(format!(
                "destination segment {component:?}: use letters, digits, '-', '_', '.', ' '"
            ));
        }
        parts.push(component);
    }
    Ok(parts.join("/"))
}

/// Joins already-admitted components under a base directory. Re-checks each
/// component so a future caller that skipped admission cannot build a path
/// escaping the base; [`admit_component`] remains the policy layer applied to
/// client input.
pub fn join_under(base: &Path, components: &[String]) -> Result<PathBuf, String> {
    let mut path = base.to_path_buf();
    for component in components {
        if component.is_empty()
            || component == "."
            || component == ".."
            || component
                .chars()
                .any(|ch| ch == '/' || ch == '\\' || ch == '\0')
        {
            return Err(format!("unsafe path component {component:?}"));
        }
        path.push(component);
    }
    Ok(path)
}

/// Produces `name`, `name-1`, `name-2`, ... keeping the extension.
pub fn with_suffix(name: &str, attempt: u32) -> String {
    if attempt == 0 {
        return name.to_owned();
    }
    match name.rsplit_once('.') {
        Some((stem, extension)) if !stem.is_empty() => {
            format!("{stem}-{attempt}.{extension}")
        }
        _ => format!("{name}-{attempt}"),
    }
}

/// Removes staging files orphaned by a crash or kill. The idle sweep only
/// covers sessions this process created; anything left on disk from a previous
/// boot would otherwise live forever. vot-sdk-file stages each object as
/// `<name>.stage` (plus `<name>.journal` under the Balanced profile) next to
/// its destination, where `<name>` always starts with `.vot-`; nothing else
/// matches that shape.
pub fn clean_staging(root: &Path) {
    #[cfg(unix)]
    fn is_staging(name: &str) -> bool {
        name.starts_with(".vot-") && (name.ends_with(".stage") || name.ends_with(".journal"))
    }
    #[cfg(not(unix))]
    let _ = root;
    #[cfg(unix)]
    walk(root, &mut |path, name| {
        if is_staging(name) {
            let _ = std::fs::remove_file(path);
        }
    });
}

#[cfg(unix)]
fn walk(dir: &Path, visit: &mut impl FnMut(&Path, &str)) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        match entry.file_type() {
            Ok(file_type) if file_type.is_dir() => {
                walk(&entry.path(), visit);
            }
            Ok(_) => visit(&entry.path(), &name),
            Err(_) => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn components_reject_traversal_and_hidden() {
        assert!(admit_component("report.pdf", false).is_ok());
        assert!(admit_component("..", true).is_err());
        assert!(admit_component("a/b", true).is_err());
        assert!(admit_component("a\\b", true).is_err());
        assert!(admit_component(".env", false).is_err());
        assert!(admit_component(".env", true).is_ok());
        assert!(admit_component("", true).is_err());
    }

    #[test]
    fn dest_normalizes_and_rejects_escape() {
        assert_eq!(admit_dest("").unwrap(), "");
        assert_eq!(admit_dest("/clients/acme/").unwrap(), "clients/acme");
        assert!(admit_dest("a/../b").is_err());
        assert!(admit_dest(".hidden").is_err());
        assert!(admit_dest("a//b").is_err());
    }

    #[test]
    fn suffixes_keep_extensions() {
        assert_eq!(with_suffix("report.pdf", 0), "report.pdf");
        assert_eq!(with_suffix("report.pdf", 2), "report-2.pdf");
        assert_eq!(with_suffix("README", 1), "README-1");
        assert_eq!(with_suffix(".env", 1), ".env-1");
    }

    #[test]
    fn clean_staging_removes_only_vot_stage_files() {
        let directory = tempfile::tempdir().unwrap();
        let nested = directory.path().join("sub");
        std::fs::create_dir(&nested).unwrap();
        let orphan = directory.path().join(".vot-1a2b-0-3c4d.stage");
        let journal = nested.join(".vot-1a2b-1-3c4d.journal");
        let kept = directory.path().join("report.pdf");
        let foreign = directory.path().join(".vot-notes.txt");
        for path in [&orphan, &journal, &kept, &foreign] {
            std::fs::write(path, b"x").unwrap();
        }
        clean_staging(directory.path());
        assert!(!orphan.exists());
        assert!(!journal.exists());
        assert!(kept.exists());
        assert!(foreign.exists());
    }

    #[test]
    fn join_under_refuses_escape_attempts() {
        let base = Path::new("/receive");
        let ok = |parts: &[&str]| {
            let owned: Vec<String> = parts.iter().map(|p| (*p).to_owned()).collect();
            join_under(base, &owned)
        };
        assert_eq!(ok(&["a", "b.txt"]).unwrap(), Path::new("/receive/a/b.txt"));
        for bad in [
            vec![".."],
            vec!["a", ".."],
            vec![""],
            vec!["."],
            vec!["a/b"],
            vec!["a\\b"],
        ] {
            let components: Vec<String> = bad.iter().map(|p| (*p).to_owned()).collect();
            assert!(join_under(base, &components).is_err(), "{bad:?}");
        }
    }
}

//! Upload sessions: one worker thread per session owns all VOT state.
//!
//! The VOT SDK objects (`PackageIngest`, `NativeFile`) are kept on a single
//! dedicated thread per session; async handlers talk to it over a bounded
//! channel. That serializes disk writes per session and keeps the SDK types
//! off the async executor entirely.

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Instant;

use axum::body::Bytes;
use serde::Serialize;
use tokio::sync::{mpsc, oneshot};

use vot_sdk::object::ObjectId;
use vot_sdk::package::{EntryStorage, PackageEntry, PackageIngest};
use vot_sdk::verify::verify_range;
use vot_sdk_file::{CommitProfile, NativeFile, RangeStatus};

use crate::paths;
use crate::store::{now_unix, FileRecord, Store, UploadRecord};

pub const MAX_SEAL_BYTES: usize = 1024 * 1024;
pub const MAX_PAGE_BYTES: usize = 4 * 1024 * 1024;
pub const MAX_PAGES: u64 = 4096;
pub const MAX_ENTRIES: usize = 20_000;
/// Covered bytes the client sends per chunk request.
pub const CHUNK_BYTES: u64 = 8 * 1024 * 1024;
/// Body cap for one chunk request (data + proof + slack).
pub const MAX_CHUNK_BODY_BYTES: usize = 9 * 1024 * 1024;
const MAX_NAME_ATTEMPTS: u32 = 100;

#[derive(Debug)]
pub struct SessionError {
    pub status: u16,
    pub message: String,
}

impl SessionError {
    fn bad(message: impl Into<String>) -> Self {
        Self {
            status: 422,
            message: message.into(),
        }
    }

    fn conflict(message: impl Into<String>) -> Self {
        Self {
            status: 409,
            message: message.into(),
        }
    }

    fn internal(message: impl Into<String>) -> Self {
        Self {
            status: 500,
            message: message.into(),
        }
    }
}

type Reply<T> = oneshot::Sender<Result<T, SessionError>>;

pub enum Cmd {
    Seal {
        bytes: Bytes,
        reply: Reply<u64>,
    },
    Page {
        bytes: Bytes,
        reply: Reply<u64>,
    },
    Begin {
        reply: Reply<Vec<EntryInfo>>,
    },
    Chunk {
        entry: usize,
        offset: u64,
        proof: Bytes,
        data: Bytes,
        reply: Reply<ChunkProgress>,
    },
    Finish {
        reply: Reply<FinishReport>,
    },
    /// Sender gave up; lets the worker record a "cancelled" event before it
    /// exits, instead of the generic "interrupted" the drop path records.
    Abort {
        reply: Reply<()>,
    },
}

#[derive(Clone, Debug, Serialize)]
pub struct EntryInfo {
    pub index: usize,
    pub path: String,
    pub stored_as: String,
    pub bytes: u64,
    pub complete: bool,
    /// Bytes verified and written contiguously from offset zero. Chunks land
    /// out of order, so this is the offset a resuming sender restarts from;
    /// the total accepted count would make it skip holes.
    pub covered_bytes: u64,
}

#[derive(Clone, Debug, Serialize)]
pub struct ChunkProgress {
    pub accepted: bool,
    pub replay: bool,
    pub covered_bytes: u64,
    pub total_bytes: u64,
    pub complete: bool,
}

#[derive(Clone, Debug, Serialize)]
pub struct FinishReport {
    pub upload_id: String,
    pub files: Vec<FileRecord>,
}

/// Everything a worker needs that outlives one request.
pub struct WorkerSetup {
    pub store: Arc<Store>,
    pub link_id: String,
    /// Absolute directory this session publishes into.
    pub dest_dir: PathBuf,
    /// Prefix of `dest_dir` relative to the receive root, for records.
    pub dest_rel: String,
    pub expected_package: ObjectId,
    pub max_total_bytes: u64,
    pub allow_hidden: bool,
    pub signer: Arc<crate::receipt::ReceiptSigner>,
    /// The session id bytes, carried into issued receipts.
    pub session_id: [u8; 16],
    /// When the session was created, for duration/rate feedback.
    pub started_at: u64,
}

struct FileState {
    display_path: String,
    stored_components: Vec<String>,
    object: ObjectId,
    native: Option<NativeFile>,
    published: bool,
    receipt: bool,
}

// One Phase exists per session; the variant size gap is irrelevant here.
#[allow(clippy::large_enum_variant)]
enum Phase {
    AwaitSeal,
    Pages {
        ingest: PackageIngest,
        entries: Vec<PackageEntry>,
        pages_pushed: u64,
    },
    Receiving {
        files: Vec<FileState>,
    },
    Done,
}

pub fn spawn_worker(setup: WorkerSetup) -> mpsc::Sender<Cmd> {
    // Depth matches the client's chunk concurrency so handlers rarely block on
    // send. Queued chunks are Bytes aliasing the request bodies, not copies,
    // so the queue holds refcounts rather than duplicated buffers.
    let (sender, mut receiver) = mpsc::channel::<Cmd>(8);
    std::thread::spawn(move || {
        let mut phase = Phase::AwaitSeal;
        // Feedback for the admin: bytes newly accepted this session and the
        // last error handed to the sender, recorded if the session dies.
        let mut received: u64 = 0;
        let mut replays: u64 = 0;
        let mut rejected: u64 = 0;
        let mut last_error: Option<String> = None;
        // When the sender was last heard from. The worker only exits long
        // after that (the idle sweep), so stamping the event with now_unix()
        // there would date a five-minute failure two days late.
        let mut last_seen = now_unix();
        // Remembers the error message, then hands the result to the sender.
        macro_rules! send_noted {
            ($reply:expr, $result:expr) => {{
                let result = $result;
                if let Err(error) = &result {
                    last_error = Some(error.message.clone());
                }
                let _ = $reply.send(result);
            }};
        }
        while let Some(cmd) = receiver.blocking_recv() {
            last_seen = now_unix();
            match cmd {
                Cmd::Seal { bytes, reply } => {
                    send_noted!(reply, handle_seal(&setup, &mut phase, &bytes));
                }
                Cmd::Page { bytes, reply } => {
                    send_noted!(reply, handle_page(&mut phase, &bytes));
                }
                Cmd::Begin { reply } => {
                    let result = handle_begin(&setup, &mut phase);
                    // A failed begin has consumed the pages: the phase is
                    // already Done, the worker exits below, and the exit-time
                    // "interrupted" fall-through is skipped. Record it here.
                    if let Err(error) = &result {
                        if matches!(phase, Phase::Done) {
                            record_event(
                                &setup,
                                received,
                                last_seen,
                                "rejected",
                                error.message.clone(),
                                replays,
                                rejected,
                            );
                        }
                    }
                    send_noted!(reply, result);
                }
                Cmd::Chunk {
                    entry,
                    offset,
                    proof,
                    data,
                    reply,
                } => {
                    let result = handle_chunk(&setup, &mut phase, entry, offset, &proof, &data);
                    match &result {
                        Ok(progress) if progress.replay => replays += 1,
                        Ok(progress) if progress.accepted => received += data.len() as u64,
                        Ok(_) => {}
                        Err(_) => rejected += 1,
                    }
                    send_noted!(reply, result);
                }
                Cmd::Finish { reply } => {
                    send_noted!(reply, handle_finish(&setup, &mut phase, replays, rejected));
                }
                Cmd::Abort { reply } => {
                    record_event(
                        &setup,
                        received,
                        last_seen,
                        "cancelled",
                        "cancelled by the sender".to_owned(),
                        replays,
                        rejected,
                    );
                    phase = Phase::Done;
                    let _ = reply.send(Ok(()));
                }
            }
            if matches!(phase, Phase::Done) {
                break;
            }
        }
        if !matches!(phase, Phase::Done) {
            record_event(
                &setup,
                received,
                last_seen,
                "interrupted",
                last_error.unwrap_or_else(|| {
                    "session went idle and expired; the sender likely disconnected".to_owned()
                }),
                replays,
                rejected,
            );
        }
        // Dropping unpublished NativeFile values removes their staging.
    });
    sender
}

fn handle_seal(setup: &WorkerSetup, phase: &mut Phase, bytes: &[u8]) -> Result<u64, SessionError> {
    if !matches!(phase, Phase::AwaitSeal) {
        return Err(SessionError::conflict("seal was already provided"));
    }
    let ingest = PackageIngest::new_expected(bytes, &setup.expected_package)
        .map_err(|error| SessionError::bad(format!("seal rejected: {:?}", error.code())))?;
    let pages = ingest.page_count();
    if pages == 0 || pages > MAX_PAGES {
        return Err(SessionError::bad(format!(
            "manifest page count {pages} outside 1..={MAX_PAGES}"
        )));
    }
    *phase = Phase::Pages {
        ingest,
        entries: Vec::new(),
        pages_pushed: 0,
    };
    Ok(pages)
}

fn handle_page(phase: &mut Phase, bytes: &[u8]) -> Result<u64, SessionError> {
    let Phase::Pages {
        ingest,
        entries,
        pages_pushed,
    } = phase
    else {
        return Err(SessionError::conflict(
            "manifest pages are not expected in this state",
        ));
    };
    let page = ingest.push_page(bytes).map_err(|error| {
        SessionError::bad(format!("manifest page rejected: {:?}", error.code()))
    })?;
    let new_entries = page.into_entries();
    if entries.len() + new_entries.len() > MAX_ENTRIES {
        return Err(SessionError::bad(format!(
            "package exceeds {MAX_ENTRIES} entries"
        )));
    }
    entries.extend(new_entries);
    *pages_pushed += 1;
    Ok(ingest.page_count().saturating_sub(*pages_pushed))
}

fn handle_begin(setup: &WorkerSetup, phase: &mut Phase) -> Result<Vec<EntryInfo>, SessionError> {
    // Begin is idempotent once receiving: a client that lost its connection
    // (or its page) calls it again to learn how far each entry got, and picks
    // up from there. Without this a reconnect could only start over.
    if let Phase::Receiving { files } = phase {
        return Ok(entry_infos(setup, files));
    }
    let Phase::Pages {
        ingest: _,
        entries,
        pages_pushed: _,
    } = phase
    else {
        return Err(SessionError::conflict(
            "begin is only valid after the seal and all pages",
        ));
    };
    let entries = std::mem::take(entries);
    let Phase::Pages { ingest, .. } = std::mem::replace(phase, Phase::Done) else {
        unreachable!("phase was matched as Pages above");
    };
    // finish() authenticates every buffered page against the expected root.
    ingest
        .finish()
        .map_err(|error| SessionError::bad(format!("manifest rejected: {:?}", error.code())))?;

    let mut total: u64 = 0;
    for entry in &entries {
        if !matches!(entry.storage(), EntryStorage::Direct) {
            return Err(SessionError::bad(
                "packed entries are not supported by votport",
            ));
        }
        for component in entry.path() {
            paths::admit_component(component, setup.allow_hidden).map_err(SessionError::bad)?;
        }
        total = total
            .checked_add(entry.object_id().length)
            .ok_or_else(|| SessionError::bad("total upload size overflows"))?;
    }
    if total > setup.max_total_bytes {
        return Err(SessionError::bad(format!(
            "upload of {total} bytes exceeds the {} byte limit for this link",
            setup.max_total_bytes
        )));
    }

    fs::create_dir_all(&setup.dest_dir)
        .map_err(|error| SessionError::internal(format!("create destination: {error}")))?;
    paths::tighten_dir(&setup.dest_dir);

    // Files this link already delivered, for dedupe on identical roots.
    let prior_uploads = setup
        .store
        .link(&setup.link_id)
        .map(|link| link.uploads)
        .unwrap_or_default();

    let mut files = Vec::with_capacity(entries.len());
    for entry in &entries {
        if let Some(existing) = find_delivered(setup, &prior_uploads, &entry.object_id()) {
            files.push(FileState {
                display_path: entry.path().collect::<Vec<_>>().join("/"),
                stored_components: existing.stored_components,
                object: entry.object_id(),
                native: None,
                published: true,
                receipt: existing.receipt,
            });
            continue;
        }
        files.push(open_destination(setup, entry)?);
    }

    // Zero-length objects have complete coverage already; publish now.
    for file in &mut files {
        if file.object.length == 0 && !file.published {
            publish_file(setup, file)?;
        }
    }

    let infos = entry_infos(setup, &files);
    *phase = Phase::Receiving { files };
    Ok(infos)
}

fn entry_infos(setup: &WorkerSetup, files: &[FileState]) -> Vec<EntryInfo> {
    files
        .iter()
        .enumerate()
        .map(|(index, file)| EntryInfo {
            index,
            path: file.display_path.clone(),
            stored_as: stored_rel(&setup.dest_rel, &file.stored_components),
            bytes: file.object.length,
            complete: file.published,
            // A published file has no live handle left to ask, and its
            // coverage is by definition the whole object.
            covered_bytes: if file.published {
                file.object.length
            } else {
                file.native
                    .as_ref()
                    .map_or(0, |native| native.progress().prefix_bytes)
            },
        })
        .collect()
}

struct Delivered {
    stored_components: Vec<String>,
    receipt: bool,
}

/// A file with this object root already delivered on this link and still on
/// disk at its recorded name: the transfer is skipped and the existing copy
/// reported, instead of publishing a suffixed duplicate.
fn find_delivered(
    setup: &WorkerSetup,
    uploads: &[UploadRecord],
    object: &ObjectId,
) -> Option<Delivered> {
    let suite = suite_name(object.suite);
    let root = hex::encode(object.root);
    for record in uploads.iter().flat_map(|upload| &upload.files) {
        if record.deleted || record.root != root || record.suite != suite {
            continue;
        }
        // stored_as is relative to the receive root. A record made under a
        // different link dest no longer lives beneath dest_dir; skip it.
        let rel = if setup.dest_rel.is_empty() {
            record.stored_as.as_str()
        } else {
            match record
                .stored_as
                .strip_prefix(&format!("{}/", setup.dest_rel))
            {
                Some(rest) => rest,
                None => continue,
            }
        };
        let components: Vec<String> = rel.split('/').map(str::to_owned).collect();
        let Ok(path) = paths::join_under(&setup.dest_dir, &components) else {
            continue;
        };
        match fs::metadata(&path) {
            Ok(meta) if meta.is_file() && meta.len() == object.length => {
                return Some(Delivered {
                    stored_components: components,
                    receipt: record.receipt,
                });
            }
            _ => {}
        }
    }
    None
}

fn open_destination(setup: &WorkerSetup, entry: &PackageEntry) -> Result<FileState, SessionError> {
    let components: Vec<String> = entry.path().map(str::to_owned).collect();
    let display_path = components.join("/");
    let object = entry.object_id();
    let parent = |stored: &[String]| {
        paths::join_under(&setup.dest_dir, &stored[..stored.len() - 1])
            .map_err(SessionError::internal)
    };
    if components.len() > 1 {
        let parent = parent(&components)?;
        fs::create_dir_all(&parent)
            .map_err(|error| SessionError::internal(format!("create folders: {error}")))?;
        // Staging lands in this parent; see paths::tighten_dir.
        paths::tighten_dir(&parent);
    }
    let name = components.last().expect("manifest paths are never empty");
    for attempt in 0..MAX_NAME_ATTEMPTS {
        let mut stored = components.clone();
        *stored.last_mut().expect("non-empty") = paths::with_suffix(name, attempt);
        // The full stored path including the file name; `parent` above is
        // only for creating intermediate directories.
        let destination =
            paths::join_under(&setup.dest_dir, &stored).map_err(SessionError::internal)?;
        match NativeFile::create(&object, &destination, CommitProfile::Balanced) {
            Ok(native) => {
                return Ok(FileState {
                    display_path,
                    stored_components: stored,
                    object,
                    native: Some(native),
                    published: false,
                    receipt: false,
                });
            }
            Err(error) if error.kind() == vot_sdk_file::ErrorKind::AlreadyExists => {}
            Err(error) => {
                return Err(SessionError::internal(format!(
                    "prepare {display_path}: {error}"
                )));
            }
        }
    }
    Err(SessionError::conflict(format!(
        "could not find a free name for {display_path}"
    )))
}

fn handle_chunk(
    setup: &WorkerSetup,
    phase: &mut Phase,
    entry: usize,
    offset: u64,
    proof: &[u8],
    data: &[u8],
) -> Result<ChunkProgress, SessionError> {
    let Phase::Receiving { files } = phase else {
        return Err(SessionError::conflict(
            "chunks are only accepted after begin",
        ));
    };
    let file = files
        .get_mut(entry)
        .ok_or_else(|| SessionError::bad(format!("no entry {entry}")))?;
    if file.published {
        // The file already verified completely; treat retries as replays.
        return Ok(ChunkProgress {
            accepted: false,
            replay: true,
            covered_bytes: file.object.length,
            total_bytes: file.object.length,
            complete: true,
        });
    }
    let verified = verify_range(&file.object, offset, data, proof).map_err(|error| {
        SessionError::bad(format!(
            "range at offset {offset} failed verification: {:?}",
            error.code()
        ))
    })?;
    let native = file
        .native
        .as_mut()
        .ok_or_else(|| SessionError::internal("file state lost"))?;
    let acceptance = native
        .accept(&verified)
        .map_err(|error| SessionError::internal(format!("write failed: {error}")))?;
    let complete = acceptance.progress.covered_bytes == acceptance.progress.total_bytes;
    if complete {
        publish_file(setup, file)?;
    }
    Ok(ChunkProgress {
        accepted: matches!(acceptance.status, RangeStatus::Accepted),
        replay: matches!(acceptance.status, RangeStatus::Replay),
        covered_bytes: acceptance.progress.covered_bytes,
        total_bytes: acceptance.progress.total_bytes,
        complete,
    })
}

fn publish_file(setup: &WorkerSetup, file: &mut FileState) -> Result<(), SessionError> {
    let native = file
        .native
        .as_mut()
        .ok_or_else(|| SessionError::internal("file state lost"))?;
    native.publish().map_err(|error| {
        SessionError::conflict(format!(
            "publish {} failed: {error}; the name may have been taken mid-upload, retry the upload",
            file.display_path
        ))
    })?;
    // Best effort: the file is delivered and verified either way, and the
    // record notes whether its receipt exists.
    if let Some(observation) = native.publish_observation() {
        let destination = paths::join_under(&setup.dest_dir, &file.stored_components);
        match destination
            .map_err(|error| error.to_string())
            .and_then(|destination| {
                setup.signer.write_sidecar(
                    &destination,
                    &file.object,
                    setup.session_id,
                    observation,
                )
            }) {
            Ok(_) => file.receipt = true,
            Err(error) => tracing::warn!(file = %file.display_path, "receipt: {error}"),
        }
    }
    file.published = true;
    file.native = None;
    Ok(())
}

fn handle_finish(
    setup: &WorkerSetup,
    phase: &mut Phase,
    replays: u64,
    rejected: u64,
) -> Result<FinishReport, SessionError> {
    let Phase::Receiving { files } = phase else {
        return Err(SessionError::conflict("nothing to finish in this state"));
    };
    if let Some(file) = files.iter().find(|file| !file.published) {
        return Err(SessionError::bad(format!(
            "{} is not fully received yet",
            file.display_path
        )));
    }
    let records: Vec<FileRecord> = files
        .iter()
        .map(|file| FileRecord {
            path: file.display_path.clone(),
            stored_as: stored_rel(&setup.dest_rel, &file.stored_components),
            bytes: file.object.length,
            suite: suite_name(file.object.suite),
            root: hex::encode(file.object.root),
            receipt: file.receipt,
            deleted: false,
        })
        .collect();
    let upload = UploadRecord {
        id: crate::auth::random_token(),
        started_at: setup.started_at,
        completed_at: now_unix(),
        replayed_chunks: replays,
        rejected_chunks: rejected,
        package_root: hex::encode(setup.expected_package.root),
        total_bytes: records.iter().map(|record| record.bytes).sum(),
        files: records.clone(),
    };
    let upload_id = upload.id.clone();
    setup
        .store
        .update_link(&setup.link_id, |link| link.uploads.push(upload))
        .map_err(SessionError::internal)?;
    *phase = Phase::Done;
    Ok(FinishReport {
        upload_id,
        files: records,
    })
}

/// How many failed/cancelled session events each link keeps, oldest dropped.
const EVENTS_KEPT: usize = 20;

/// Best effort: feedback must never fail a session, so the store error is
/// dropped. `expected_bytes` is the whole package (manifest included) while
/// `received` counts file payload only, so a near-complete session can read
/// slightly under 100%.
fn record_event(
    setup: &WorkerSetup,
    received: u64,
    at: u64,
    outcome: &str,
    detail: String,
    replays: u64,
    rejected: u64,
) {
    let event = crate::store::SessionEvent {
        at,
        started_at: setup.started_at,
        outcome: outcome.to_owned(),
        detail,
        received_bytes: received,
        expected_bytes: setup.expected_package.length,
        replayed_chunks: replays,
        rejected_chunks: rejected,
    };
    let _ = setup.store.update_link(&setup.link_id, |link| {
        link.events.push(event);
        if link.events.len() > EVENTS_KEPT {
            let excess = link.events.len() - EVENTS_KEPT;
            link.events.drain(..excess);
        }
    });
}

fn stored_rel(dest_rel: &str, components: &[String]) -> String {
    let tail = components.join("/");
    if dest_rel.is_empty() {
        tail
    } else {
        format!("{dest_rel}/{tail}")
    }
}

pub fn suite_name(identifier: u16) -> String {
    match identifier {
        1 => "blake3".to_owned(),
        2 => "sha256".to_owned(),
        other => format!("suite-{other}"),
    }
}

/// Registry of live sessions reachable from async handlers.
pub struct Sessions {
    map: Mutex<HashMap<String, SessionHandle>>,
}

pub struct SessionHandle {
    pub link_id: String,
    pub sender: mpsc::Sender<Cmd>,
    pub last_active: Instant,
}

impl Default for Sessions {
    fn default() -> Self {
        Self::new()
    }
}

impl Sessions {
    pub fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::new()),
        }
    }

    pub fn insert(&self, id: String, link_id: String, sender: mpsc::Sender<Cmd>) {
        self.map.lock().expect("sessions poisoned").insert(
            id,
            SessionHandle {
                link_id,
                sender,
                last_active: Instant::now(),
            },
        );
    }

    /// The link a session belongs to, for completion notifications.
    pub fn link_id(&self, id: &str) -> Option<String> {
        self.map
            .lock()
            .expect("sessions poisoned")
            .get(id)
            .map(|handle| handle.link_id.clone())
    }

    /// Returns the sender for a session and refreshes its idle clock.
    pub fn touch(&self, id: &str) -> Option<mpsc::Sender<Cmd>> {
        let mut map = self.map.lock().expect("sessions poisoned");
        let handle = map.get_mut(id)?;
        handle.last_active = Instant::now();
        Some(handle.sender.clone())
    }

    pub fn remove(&self, id: &str) {
        self.map.lock().expect("sessions poisoned").remove(id);
    }

    pub fn total(&self) -> usize {
        self.map.lock().expect("sessions poisoned").len()
    }

    pub fn active_for_link(&self, link_id: &str) -> usize {
        self.map
            .lock()
            .expect("sessions poisoned")
            .values()
            .filter(|handle| handle.link_id == link_id)
            .count()
    }

    /// Drops sessions idle beyond `idle_secs`; their workers then exit and
    /// clean up staging files.
    pub fn sweep(&self, idle_secs: u64) {
        self.map
            .lock()
            .expect("sessions poisoned")
            .retain(|_, handle| handle.last_active.elapsed().as_secs() < idle_secs);
    }
}

//! Persistent state: request links and their completed uploads.
//!
//! Everything lives in one JSON document written atomically (temp file +
//! rename) under the data directory. Scale target is a personal server, so a
//! mutex around one document is deliberate.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct FileRecord {
    /// Path as named inside the uploaded package.
    pub path: String,
    /// Path actually stored on disk, relative to the receive root.
    pub stored_as: String,
    pub bytes: u64,
    /// Hash suite of the object root ("blake3" or "sha256").
    pub suite: String,
    /// Hex object root the received bytes verified against.
    pub root: String,
    /// Whether a signed `.vot-receipt` sidecar was written next to the file.
    #[serde(default)]
    pub receipt: bool,
    /// Set when the admin deleted the stored file. The freed name can be
    /// reused by later, different content, so a tombstoned record must never
    /// satisfy dedupe even if a same-length file sits at its path again.
    #[serde(default)]
    pub deleted: bool,
}

/// A session that ended without a completed upload: cancelled by the sender
/// or interrupted (disconnect, expiry, terminal error). Kept per link, newest
/// last, capped, so the admin can see what went wrong and how far it got.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SessionEvent {
    pub at: u64,
    pub started_at: u64,
    /// "cancelled", "interrupted", or "rejected" (begin refused the package).
    pub outcome: String,
    pub detail: String,
    pub received_bytes: u64,
    pub expected_bytes: u64,
    /// Chunks the sender re-sent that were already verified: retries after a
    /// response was lost in transit, so a proxy for how flaky the line was.
    /// (TCP hides actual wire loss; there is no FEC at this layer.)
    #[serde(default)]
    pub replayed_chunks: u64,
    /// Chunks the server refused (bad proof, bounds, state).
    #[serde(default)]
    pub rejected_chunks: u64,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct UploadRecord {
    pub id: String,
    /// When the session was created; 0 on records from before this field.
    #[serde(default)]
    pub started_at: u64,
    pub completed_at: u64,
    /// See [`SessionEvent::replayed_chunks`].
    #[serde(default)]
    pub replayed_chunks: u64,
    #[serde(default)]
    pub rejected_chunks: u64,
    /// Hex root of the verified package manifest.
    pub package_root: String,
    pub total_bytes: u64,
    pub files: Vec<FileRecord>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Link {
    pub id: String,
    pub label: String,
    /// Destination subdirectory relative to the receive root ("" = root).
    pub dest: String,
    #[serde(default)]
    pub password_hash: Option<String>,
    pub created_at: u64,
    #[serde(default)]
    pub expires_at: Option<u64>,
    #[serde(default)]
    pub max_bytes: Option<u64>,
    pub active: bool,
    #[serde(default)]
    pub uploads: Vec<UploadRecord>,
    #[serde(default)]
    pub events: Vec<SessionEvent>,
}

impl Link {
    pub fn usable_now(&self) -> bool {
        self.active && self.expires_at.is_none_or(|at| now_unix() < at)
    }
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct Document {
    #[serde(default)]
    links: Vec<Link>,
    /// Argon2 PHC hash set by "change password" in the admin UI. Once present
    /// it wins over VOTPORT_ADMIN_PASSWORD, so a restart cannot silently roll
    /// the password back to whatever the environment still holds. To recover a
    /// lost password, delete this field from state.json and restart.
    #[serde(default)]
    admin_password_hash: Option<String>,
}

pub struct Store {
    path: PathBuf,
    document: Mutex<Document>,
}

impl Store {
    pub fn open(data_dir: &Path) -> Result<Self, String> {
        fs::create_dir_all(data_dir)
            .map_err(|error| format!("create {}: {error}", data_dir.display()))?;
        let path = data_dir.join("state.json");
        let document = match fs::read(&path) {
            Ok(bytes) => serde_json::from_slice(&bytes)
                .map_err(|error| format!("parse {}: {error}", path.display()))?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Document::default(),
            Err(error) => return Err(format!("read {}: {error}", path.display())),
        };
        Ok(Self {
            path,
            document: Mutex::new(document),
        })
    }

    pub fn admin_password_hash(&self) -> Option<String> {
        self.document
            .lock()
            .expect("store poisoned")
            .admin_password_hash
            .clone()
    }

    pub fn set_admin_password_hash(&self, hash: String) -> Result<(), String> {
        let mut document = self.document.lock().expect("store poisoned");
        document.admin_password_hash = Some(hash);
        persist(&self.path, &document)
    }

    pub fn links(&self) -> Vec<Link> {
        self.document.lock().expect("store poisoned").links.clone()
    }

    pub fn link(&self, id: &str) -> Option<Link> {
        self.document
            .lock()
            .expect("store poisoned")
            .links
            .iter()
            .find(|link| link.id == id)
            .cloned()
    }

    pub fn insert_link(&self, link: Link) -> Result<(), String> {
        let mut document = self.document.lock().expect("store poisoned");
        document.links.push(link);
        persist(&self.path, &document)
    }

    /// Applies `mutate` to the link and persists; Ok(false) when absent.
    pub fn update_link(&self, id: &str, mutate: impl FnOnce(&mut Link)) -> Result<bool, String> {
        let mut document = self.document.lock().expect("store poisoned");
        let Some(link) = document.links.iter_mut().find(|link| link.id == id) else {
            return Ok(false);
        };
        mutate(link);
        persist(&self.path, &document).map(|()| true)
    }

    pub fn remove_link(&self, id: &str) -> Result<bool, String> {
        let mut document = self.document.lock().expect("store poisoned");
        let before = document.links.len();
        document.links.retain(|link| link.id != id);
        if document.links.len() == before {
            return Ok(false);
        }
        persist(&self.path, &document).map(|()| true)
    }
}

fn persist(path: &Path, document: &Document) -> Result<(), String> {
    let bytes = serde_json::to_vec_pretty(document).map_err(|error| error.to_string())?;
    let temp = path.with_extension("json.tmp");
    // 0600: the document holds the argon2 admin and link password hashes.
    crate::auth::write_private(&temp, &bytes)
        .map_err(|error| format!("write {}: {error}", temp.display()))?;
    fs::rename(&temp, path).map_err(|error| error.to_string())?;
    // The rename is only durable once its directory entry is.
    if let Ok(dir) = fs::File::open(path.parent().unwrap_or(Path::new("."))) {
        let _ = dir.sync_all();
    }
    Ok(())
}

pub fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |duration| duration.as_secs())
}

//! Passwords (argon2id) and stateless signed admin sessions.

use std::sync::Mutex;
use std::time::{Duration, Instant};

use argon2::password_hash::rand_core::OsRng;
use argon2::password_hash::{PasswordHash, PasswordHasher as _, PasswordVerifier as _, SaltString};
use argon2::Argon2;
use hmac::{Hmac, Mac as _};
use rand::RngCore as _;
use sha2::Sha256;

use crate::store::now_unix;

const ADMIN_SESSION_SECS: u64 = 7 * 24 * 3600;
const LOCKOUT_THRESHOLD: u32 = 5;
const LOCKOUT_SECS: u64 = 60;

pub fn hash_password(password: &str) -> Result<String, String> {
    let salt = SaltString::generate(&mut OsRng);
    Argon2::default()
        .hash_password(password.as_bytes(), &salt)
        .map(|hash| hash.to_string())
        .map_err(|error| error.to_string())
}

pub fn verify_password(password: &str, phc: &str) -> bool {
    PasswordHash::new(phc).is_ok_and(|parsed| {
        Argon2::default()
            .verify_password(password.as_bytes(), &parsed)
            .is_ok()
    })
}

pub fn random_token() -> String {
    let mut bytes = [0u8; 16];
    rand::rngs::OsRng.fill_bytes(&mut bytes);
    hex::encode(bytes)
}

/// Loads or creates the 32-byte cookie-signing secret in the data directory.
pub fn load_secret(data_dir: &std::path::Path) -> Result<[u8; 32], String> {
    let path = data_dir.join("secret");
    match std::fs::read(&path) {
        Ok(bytes) if bytes.len() == 32 => {
            let mut secret = [0u8; 32];
            secret.copy_from_slice(&bytes);
            Ok(secret)
        }
        Ok(_) => Err(format!("{} is not a 32-byte secret", path.display())),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            let mut secret = [0u8; 32];
            rand::rngs::OsRng.fill_bytes(&mut secret);
            write_private(&path, &secret).map_err(|error| error.to_string())?;
            Ok(secret)
        }
        Err(error) => Err(format!("read {}: {error}", path.display())),
    }
}

/// Creates a file readable only by its owner from the first instant: writing
/// with default permissions and tightening afterwards leaves a window where
/// the secret is world-readable on disk.
pub fn write_private(path: &std::path::Path, bytes: &[u8]) -> std::io::Result<()> {
    use std::io::Write as _;
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    file.write_all(bytes)?;
    file.sync_all()
}

fn token_mac(secret: &[u8; 32], context: &[&[u8]], expires: u64, nonce: &str) -> String {
    let mut mac = Hmac::<Sha256>::new_from_slice(secret).expect("HMAC accepts 32-byte keys");
    for part in context {
        mac.update(part);
        mac.update(b"\0");
    }
    mac.update(expires.to_le_bytes().as_slice());
    mac.update(nonce.as_bytes());
    hex::encode(mac.finalize().into_bytes())
}

fn issue_token(secret: &[u8; 32], context: &[&[u8]], lifetime_secs: u64) -> String {
    let expires = now_unix() + lifetime_secs;
    let nonce = random_token();
    let mac = token_mac(secret, context, expires, &nonce);
    format!("{expires}.{nonce}.{mac}")
}

fn verify_token(secret: &[u8; 32], context: &[&[u8]], token: &str) -> bool {
    let mut parts = token.splitn(3, '.');
    let (Some(expires), Some(nonce), Some(mac)) = (parts.next(), parts.next(), parts.next()) else {
        return false;
    };
    let Ok(expires) = expires.parse::<u64>() else {
        return false;
    };
    if now_unix() >= expires {
        return false;
    }
    let expected = token_mac(secret, context, expires, nonce);
    constant_time_eq(expected.as_bytes(), mac.as_bytes())
}

/// Issues an admin session token: `expires.nonce.mac`. The MAC covers the
/// stored password hash, so changing the password via the UI invalidates
/// every outstanding session. `phc` is the state.json hash or empty when the
/// password still comes from the environment; the env-derived hash is salted
/// fresh each boot and would otherwise log the admin out on every restart.
pub fn issue_admin_token(secret: &[u8; 32], phc: &str) -> String {
    issue_token(
        secret,
        &[b"votport-admin", phc.as_bytes()],
        ADMIN_SESSION_SECS,
    )
}

pub fn verify_admin_token(secret: &[u8; 32], phc: &str, token: &str) -> bool {
    verify_token(secret, &[b"votport-admin", phc.as_bytes()], token)
}

const LINK_SESSION_SECS: u64 = 30 * 24 * 3600;

/// Issues a link access token proving the link password was verified once.
/// The MAC covers the link's password hash, so replacing the link (or its
/// password) invalidates outstanding cookies.
pub fn issue_link_token(secret: &[u8; 32], link_id: &str, phc: &str) -> String {
    issue_token(
        secret,
        &[b"votport-link", link_id.as_bytes(), phc.as_bytes()],
        LINK_SESSION_SECS,
    )
}

pub fn verify_link_token(secret: &[u8; 32], link_id: &str, phc: &str, token: &str) -> bool {
    verify_token(
        secret,
        &[b"votport-link", link_id.as_bytes(), phc.as_bytes()],
        token,
    )
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// Global login throttle: after repeated failures every login pauses briefly.
pub struct LoginThrottle {
    state: Mutex<(u32, Option<Instant>)>,
}

impl Default for LoginThrottle {
    fn default() -> Self {
        Self::new()
    }
}

impl LoginThrottle {
    pub fn new() -> Self {
        Self {
            state: Mutex::new((0, None)),
        }
    }

    pub fn locked(&self) -> bool {
        let state = self.state.lock().expect("throttle poisoned");
        state.1.is_some_and(|until| Instant::now() < until)
    }

    pub fn record(&self, success: bool) {
        let mut state = self.state.lock().expect("throttle poisoned");
        if success {
            *state = (0, None);
        } else {
            state.0 += 1;
            if state.0 >= LOCKOUT_THRESHOLD {
                state.1 = Some(Instant::now() + Duration::from_secs(LOCKOUT_SECS));
                state.0 = 0;
            }
        }
    }
}

/// Per-IP throttle for link password checks. The global [`LoginThrottle`]
/// stays admin-only: sharing it with public links let anyone holding a link
/// URL lock the admin out with five bad guesses.
struct IpState {
    failures: u32,
    locked_until: Option<Instant>,
    last_seen: Instant,
}

/// Entries idle this long carry no lockout and stale failure counts; they are
/// evicted when the table needs room.
const IP_ENTRY_TTL_SECS: u64 = 600;
const IP_TABLE_CAP: usize = 4096;

impl IpThrottle {
    pub fn new() -> Self {
        Self {
            state: Mutex::new(std::collections::HashMap::new()),
        }
    }

    pub fn locked(&self, ip: &str) -> bool {
        let state = self.state.lock().expect("throttle poisoned");
        state.get(ip).is_some_and(|entry| {
            entry
                .locked_until
                .is_some_and(|until| Instant::now() < until)
        })
    }

    pub fn record(&self, ip: &str, success: bool) {
        let mut state = self.state.lock().expect("throttle poisoned");
        if state.len() >= IP_TABLE_CAP {
            // Evict only dead weight: expired, idle entries. Live lockouts
            // survive, so filling the table cannot reset anyone's penalty.
            let now = Instant::now();
            state.retain(|_, entry| {
                entry.locked_until.is_some_and(|until| now < until)
                    || now.duration_since(entry.last_seen).as_secs() < IP_ENTRY_TTL_SECS
            });
        }
        if success {
            state.remove(ip);
            return;
        }
        let entry = state.entry(ip.to_owned()).or_insert(IpState {
            failures: 0,
            locked_until: None,
            last_seen: Instant::now(),
        });
        entry.last_seen = Instant::now();
        entry.failures += 1;
        if entry.failures >= LOCKOUT_THRESHOLD {
            entry.locked_until = Some(Instant::now() + Duration::from_secs(LOCKOUT_SECS));
            entry.failures = 0;
        }
    }
}

pub struct IpThrottle {
    state: Mutex<std::collections::HashMap<String, IpState>>,
}

impl Default for IpThrottle {
    fn default() -> Self {
        Self::new()
    }
}

/// Extracts a cookie value from a `Cookie` request header.
pub fn cookie_value<'header>(header: &'header str, name: &str) -> Option<&'header str> {
    header.split(';').find_map(|pair| {
        let (key, value) = pair.trim().split_once('=')?;
        (key == name).then_some(value)
    })
}

//! HTTP API: admin management plus the public upload protocol.

use std::sync::Arc;

use axum::body::Bytes;
use axum::extract::{ConnectInfo, Path, Query, State};
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde::{Deserialize, Serialize};
use serde_json::json;
use tokio::sync::oneshot;

use vot_sdk::object::{ObjectId, Suite};

use crate::app::App;
use crate::auth;
use crate::paths;
use crate::session::{self, Cmd, SessionError};
use crate::store::{now_unix, Link};

const ADMIN_COOKIE: &str = "votport_admin";
// Worst case memory: MAX_SESSIONS x 8 in-flight chunks x ~9 MiB of queued
// request bodies, plus each worker's pinned merkle trees. Raising these caps
// raises that ceiling linearly.
const MAX_SESSIONS: usize = 32;
const MAX_SESSIONS_PER_LINK: usize = 8;

pub struct ApiError {
    status: StatusCode,
    message: String,
}

impl ApiError {
    pub fn new(status: StatusCode, message: impl Into<String>) -> Self {
        Self {
            status,
            message: message.into(),
        }
    }

    fn unauthorized() -> Self {
        Self::new(StatusCode::UNAUTHORIZED, "not signed in")
    }

    fn not_found() -> Self {
        Self::new(StatusCode::NOT_FOUND, "not found")
    }

    fn internal(message: impl Into<String>) -> Self {
        Self::new(StatusCode::INTERNAL_SERVER_ERROR, message)
    }
}

impl From<SessionError> for ApiError {
    fn from(error: SessionError) -> Self {
        Self::new(
            StatusCode::from_u16(error.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR),
            error.message,
        )
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (self.status, Json(json!({ "error": self.message }))).into_response()
    }
}

type ApiResult<T> = Result<T, ApiError>;

// ---------------------------------------------------------------- admin auth

/// Credential tag bound into admin token MACs: the state.json hash when the
/// UI has set one, else the stable tag derived from the environment
/// credential. Either way, rotating the credential evicts sessions and a
/// plain restart does not.
fn admin_token_phc(app: &App) -> String {
    app.store
        .admin_password_hash()
        .unwrap_or_else(|| app.config.admin_token_tag.clone())
}

fn is_admin(app: &App, headers: &HeaderMap) -> bool {
    headers
        .get(header::COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookies| auth::cookie_value(cookies, ADMIN_COOKIE))
        .is_some_and(|token| auth::verify_admin_token(&app.secret, &admin_token_phc(app), token))
}

/// Client address for per-IP throttling: the rightmost X-Forwarded-For entry
/// (the one the reverse proxy appended; earlier entries are client-supplied),
/// else the socket peer.
fn client_ip(headers: &HeaderMap, peer: &std::net::SocketAddr) -> String {
    // X-Forwarded-For is honored only from a peer that can be the reverse
    // proxy (loopback or a private/ULA address). A caller reaching the port
    // directly from elsewhere would otherwise mint a fresh throttle bucket
    // per request by spoofing the header.
    if !proxy_peer(&peer.ip()) {
        return peer.ip().to_string();
    }
    headers
        .get("x-forwarded-for")
        .and_then(|value| value.to_str().ok())
        .and_then(|list| list.rsplit(',').next())
        .map(|ip| ip.trim().to_owned())
        .filter(|ip| !ip.is_empty())
        .unwrap_or_else(|| peer.ip().to_string())
}

fn proxy_peer(ip: &std::net::IpAddr) -> bool {
    // Docker bridges can present v4 peers as IPv4-mapped IPv6; unwrap those
    // so the RFC 1918 check still applies.
    let ip = match ip {
        std::net::IpAddr::V6(v6) => match v6.to_ipv4_mapped() {
            Some(v4) => std::net::IpAddr::V4(v4),
            None => return (v6.segments()[0] & 0xfe00) == 0xfc00 || v6.is_loopback(),
        },
        other => *other,
    };
    match ip {
        std::net::IpAddr::V4(v4) => v4.is_loopback() || v4.is_private(),
        // fc00::/7 unique-local, the v6 analogue of RFC 1918.
        std::net::IpAddr::V6(v6) => v6.is_loopback() || (v6.segments()[0] & 0xfe00) == 0xfc00,
    }
}

fn require_admin(app: &App, headers: &HeaderMap) -> ApiResult<()> {
    if is_admin(app, headers) {
        Ok(())
    } else {
        Err(ApiError::unauthorized())
    }
}

/// Mutating admin routes also require a custom header; cross-site forms
/// cannot set one, which closes CSRF without token bookkeeping.
fn require_admin_write(app: &App, headers: &HeaderMap) -> ApiResult<()> {
    require_admin(app, headers)?;
    if headers.contains_key("x-votport") {
        Ok(())
    } else {
        Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "missing X-Votport header",
        ))
    }
}

/// The admin password in force: a hash stored by "change password" wins over
/// the one derived from the environment at startup, so a restart does not roll
/// the password back to VOTPORT_ADMIN_PASSWORD.
fn admin_hash(app: &App) -> String {
    app.store
        .admin_password_hash()
        .unwrap_or_else(|| app.config.admin_password_hash.clone())
}

fn cookie_attributes(app: &App) -> &'static str {
    let secure = app
        .config
        .public_url
        .as_deref()
        .is_none_or(|url| url.starts_with("https://"));
    if secure {
        "; Secure"
    } else {
        ""
    }
}

#[derive(Deserialize)]
pub struct LoginRequest {
    password: String,
}

pub async fn admin_login(
    State(app): State<Arc<App>>,
    Json(request): Json<LoginRequest>,
) -> ApiResult<Response> {
    if app.throttle.locked() {
        return Err(ApiError::new(
            StatusCode::TOO_MANY_REQUESTS,
            "too many failed attempts; wait a minute",
        ));
    }
    let ok = tokio::task::spawn_blocking({
        let hash = admin_hash(&app);
        move || auth::verify_password(&request.password, &hash)
    })
    .await
    .map_err(|error| ApiError::internal(error.to_string()))?;
    app.throttle.record(ok);
    if !ok {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "wrong password"));
    }
    let token = auth::issue_admin_token(&app.secret, &admin_token_phc(&app));
    let cookie = format!(
        "{ADMIN_COOKIE}={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800{}",
        cookie_attributes(&app)
    );
    Ok(([(header::SET_COOKIE, cookie)], Json(json!({ "ok": true }))).into_response())
}

pub async fn admin_logout(State(app): State<Arc<App>>) -> Response {
    let cookie = format!(
        "{ADMIN_COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0{}",
        cookie_attributes(&app)
    );
    ([(header::SET_COOKIE, cookie)], Json(json!({ "ok": true }))).into_response()
}

pub async fn admin_session(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin(&app, &headers)?;
    Ok(Json(json!({ "ok": true })))
}

#[derive(Deserialize)]
pub struct ChangePasswordRequest {
    current: String,
    new: String,
}

/// Replaces the admin password. The new hash is persisted in state.json, which
/// from then on takes precedence over the environment. Token MACs cover that
/// hash, so every outstanding admin session is invalidated by the change; the
/// response reissues a cookie under the new hash so the acting admin stays
/// signed in.
pub async fn admin_change_password(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Json(request): Json<ChangePasswordRequest>,
) -> ApiResult<Response> {
    require_admin_write(&app, &headers)?;
    if app.throttle.locked() {
        return Err(ApiError::new(
            StatusCode::TOO_MANY_REQUESTS,
            "too many failed attempts; wait a minute",
        ));
    }
    if request.new.chars().count() < 12 {
        return Err(ApiError::new(
            StatusCode::BAD_REQUEST,
            "new password must be at least 12 characters",
        ));
    }
    let current_ok = tokio::task::spawn_blocking({
        let hash = admin_hash(&app);
        let current = request.current.clone();
        move || auth::verify_password(&current, &hash)
    })
    .await
    .map_err(|error| ApiError::internal(error.to_string()))?;
    // Throttled like login: this endpoint verifies a password too, so it would
    // otherwise be an unthrottled oracle for an attacker holding a session.
    app.throttle.record(current_ok);
    if !current_ok {
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "current password is wrong",
        ));
    }
    let hash = tokio::task::spawn_blocking(move || auth::hash_password(&request.new))
        .await
        .map_err(|error| ApiError::internal(error.to_string()))?
        .map_err(ApiError::internal)?;
    app.store
        .set_admin_password_hash(hash)
        .map_err(ApiError::internal)?;
    let token = auth::issue_admin_token(&app.secret, &admin_token_phc(&app));
    let cookie = format!(
        "{ADMIN_COOKIE}={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800{}",
        cookie_attributes(&app)
    );
    Ok(([(header::SET_COOKIE, cookie)], Json(json!({ "ok": true }))).into_response())
}

// ------------------------------------------------------------ link management

#[derive(Serialize)]
struct LinkView {
    id: String,
    label: String,
    dest: String,
    url: String,
    has_password: bool,
    created_at: u64,
    expires_at: Option<u64>,
    max_bytes: Option<u64>,
    active: bool,
    usable: bool,
    uploads: Vec<UploadView>,
    events: Vec<crate::store::SessionEvent>,
}

#[derive(Serialize)]
struct UploadView {
    id: String,
    started_at: u64,
    completed_at: u64,
    replayed_chunks: u64,
    rejected_chunks: u64,
    package_root: String,
    total_bytes: u64,
    files: Vec<FileView>,
}

#[derive(Serialize)]
struct FileView {
    path: String,
    stored_as: String,
    bytes: u64,
    suite: String,
    root: String,
    receipt: bool,
    /// Whether the stored file is still on disk right now.
    exists: bool,
}

fn base_url(app: &App, headers: &HeaderMap) -> String {
    if let Some(url) = &app.config.public_url {
        return url.clone();
    }
    let proto = headers
        .get("x-forwarded-proto")
        .and_then(|value| value.to_str().ok())
        .unwrap_or("http");
    let host = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .unwrap_or("localhost");
    format!("{proto}://{host}")
}

/// The on-disk path a file record points at, from server-recorded components
/// only; client input never reaches this. None when a stored record fails the
/// join guard (a corrupted record), which the display treats as "missing".
fn stored_path(app: &App, stored_as: &str) -> Option<std::path::PathBuf> {
    let components: Vec<String> = stored_as
        .split('/')
        .filter(|part| !part.is_empty())
        .map(str::to_owned)
        .collect();
    paths::join_under(&app.config.receive_dir, &components).ok()
}

fn link_view(app: &App, link: Link, base: &str) -> LinkView {
    let usable = link.usable_now();
    let uploads = link
        .uploads
        .into_iter()
        .map(|upload| UploadView {
            files: upload
                .files
                .into_iter()
                .map(|file| FileView {
                    exists: stored_path(app, &file.stored_as).is_some_and(|path| path.is_file()),
                    path: file.path,
                    stored_as: file.stored_as,
                    bytes: file.bytes,
                    suite: file.suite,
                    root: file.root,
                    receipt: file.receipt,
                })
                .collect(),
            id: upload.id,
            started_at: upload.started_at,
            completed_at: upload.completed_at,
            replayed_chunks: upload.replayed_chunks,
            rejected_chunks: upload.rejected_chunks,
            package_root: upload.package_root,
            total_bytes: upload.total_bytes,
        })
        .collect();
    LinkView {
        url: format!("{base}/r/{}", link.id),
        usable,
        id: link.id,
        label: link.label,
        dest: link.dest,
        has_password: link.password_hash.is_some(),
        created_at: link.created_at,
        expires_at: link.expires_at,
        max_bytes: link.max_bytes,
        active: link.active,
        uploads,
        events: link.events,
    }
}

pub async fn list_links(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin(&app, &headers)?;
    let base = base_url(&app, &headers);
    let links: Vec<LinkView> = app
        .store
        .links()
        .into_iter()
        .map(|link| link_view(&app, link, &base))
        .collect();
    Ok(Json(json!({
        "links": links,
        "receive_dir": app.config.receive_dir,
        "receipt_key": app.signer.public_hex,
    })))
}

#[derive(Deserialize)]
pub struct CreateLinkRequest {
    label: String,
    #[serde(default)]
    dest: String,
    #[serde(default)]
    password: Option<String>,
    #[serde(default)]
    expires_days: Option<u32>,
    #[serde(default)]
    max_bytes: Option<u64>,
}

pub async fn create_link(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Json(request): Json<CreateLinkRequest>,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin_write(&app, &headers)?;
    let label = request.label.trim().to_owned();
    if label.is_empty() || label.len() > 200 {
        return Err(ApiError::new(
            StatusCode::UNPROCESSABLE_ENTITY,
            "label must be 1..=200 characters",
        ));
    }
    let dest = paths::admit_dest(&request.dest)
        .map_err(|error| ApiError::new(StatusCode::UNPROCESSABLE_ENTITY, error))?;
    let password_hash = match request.password.as_deref().filter(|p| !p.is_empty()) {
        Some(password) => Some(auth::hash_password(password).map_err(ApiError::internal)?),
        None => None,
    };
    let link = Link {
        id: auth::random_token(),
        label,
        dest,
        password_hash,
        created_at: now_unix(),
        expires_at: request
            .expires_days
            .map(|days| now_unix() + u64::from(days) * 86_400),
        max_bytes: request.max_bytes.filter(|&bytes| bytes > 0),
        active: true,
        uploads: Vec::new(),
        events: Vec::new(),
    };
    let base = base_url(&app, &headers);
    let view = link_view(&app, link.clone(), &base);
    app.store.insert_link(link).map_err(ApiError::internal)?;
    Ok(Json(json!({ "link": view })))
}

#[derive(Deserialize)]
pub struct UpdateLinkRequest {
    active: bool,
}

pub async fn update_link(
    State(app): State<Arc<App>>,
    Path(id): Path<String>,
    headers: HeaderMap,
    Json(request): Json<UpdateLinkRequest>,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin_write(&app, &headers)?;
    let found = app
        .store
        .update_link(&id, |link| link.active = request.active)
        .map_err(ApiError::internal)?;
    if !found {
        return Err(ApiError::not_found());
    }
    Ok(Json(json!({ "ok": true })))
}

pub async fn delete_link(
    State(app): State<Arc<App>>,
    Path(id): Path<String>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin_write(&app, &headers)?;
    if !app.store.remove_link(&id).map_err(ApiError::internal)? {
        return Err(ApiError::not_found());
    }
    Ok(Json(json!({ "ok": true })))
}

/// The request link as a scannable SVG, for senders on phones.
pub async fn link_qr(
    State(app): State<Arc<App>>,
    Path(id): Path<String>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    require_admin(&app, &headers)?;
    let link = app.store.link(&id).ok_or_else(ApiError::not_found)?;
    let url = format!("{}/r/{}", base_url(&app, &headers), link.id);
    let code = qrcode::QrCode::new(url.as_bytes())
        .map_err(|error| ApiError::internal(error.to_string()))?;
    let svg = code
        .render::<qrcode::render::svg::Color>()
        .min_dimensions(220, 220)
        .dark_color(qrcode::render::svg::Color("#000000"))
        .light_color(qrcode::render::svg::Color("#ffffff"))
        .build();
    Ok(([(header::CONTENT_TYPE, "image/svg+xml")], svg).into_response())
}

/// Removes one upload from a link's history. Files on disk are untouched.
pub async fn delete_upload_record(
    State(app): State<Arc<App>>,
    Path((id, upload)): Path<(String, String)>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin_write(&app, &headers)?;
    let found = app
        .store
        .update_link(&id, |link| link.uploads.retain(|entry| entry.id != upload))
        .map_err(ApiError::internal)?;
    if !found {
        return Err(ApiError::not_found());
    }
    Ok(Json(json!({ "ok": true })))
}

/// Deletes one received file (and its receipt sidecar) from disk. The path
/// comes from the stored record, never from the client. Already-gone files
/// succeed: the record's existence flag is the display of truth.
pub async fn delete_received_file(
    State(app): State<Arc<App>>,
    Path((id, upload, index)): Path<(String, String, usize)>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    require_admin_write(&app, &headers)?;
    let link = app.store.link(&id).ok_or_else(ApiError::not_found)?;
    let record = link
        .uploads
        .iter()
        .find(|entry| entry.id == upload)
        .and_then(|entry| entry.files.get(index))
        .ok_or_else(ApiError::not_found)?;
    let path = stored_path(&app, &record.stored_as)
        .ok_or_else(|| ApiError::internal("stored path failed the join guard"))?;
    for target in [path.clone(), {
        let mut sidecar = path.into_os_string();
        sidecar.push(".vot-receipt");
        sidecar.into()
    }] {
        match std::fs::remove_file(&target) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(ApiError::internal(format!(
                    "delete {}: {error}",
                    target.display()
                )));
            }
        }
    }
    // Tombstone every record naming this path, not just the one deleted
    // through: the freed name can be reused by different content, and any
    // record still pointing there must never satisfy dedupe again.
    let stored_as = record.stored_as.clone();
    app.store
        .update_link(&id, |link| {
            for upload in &mut link.uploads {
                for file in &mut upload.files {
                    if file.stored_as == stored_as {
                        file.deleted = true;
                    }
                }
            }
        })
        .map_err(ApiError::internal)?;
    Ok(Json(json!({ "ok": true })))
}

// ------------------------------------------------------------- upload protocol

/// Cookie carrying proof that this link's password was verified once.
fn link_cookie_name(link_id: &str) -> String {
    format!("votport_r_{link_id}")
}

fn link_authorized(app: &App, link: &Link, headers: &HeaderMap) -> bool {
    let phc = link.password_hash.as_deref().unwrap_or_default();
    headers
        .get(header::COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookies| auth::cookie_value(cookies, &link_cookie_name(&link.id)))
        .is_some_and(|token| auth::verify_link_token(&app.secret, &link.id, phc, token))
}

pub async fn link_info(
    State(app): State<Arc<App>>,
    Path(token): Path<String>,
    headers: HeaderMap,
) -> ApiResult<Json<serde_json::Value>> {
    let link = app.store.link(&token).ok_or_else(ApiError::not_found)?;
    let usable = link.usable_now();
    Ok(Json(json!({
        // The label leaks nothing new to an authorized sender, but an old URL
        // for a closed request should not keep revealing what it was for.
        "label": if usable { Some(&link.label) } else { None },
        "needs_password": link.password_hash.is_some(),
        "authorized": link_authorized(&app, &link, &headers),
        "usable": usable,
        "max_bytes": effective_cap(&app, &link),
        "chunk_bytes": session::CHUNK_BYTES,
    })))
}

fn effective_cap(app: &App, link: &Link) -> u64 {
    link.max_bytes.map_or(app.config.max_upload_bytes, |cap| {
        cap.min(app.config.max_upload_bytes)
    })
}

#[derive(Deserialize)]
pub struct PackageAnnouncement {
    /// "blake3" or "sha256" — package roots are blake3 today, but the wire
    /// format carries the suite so the client stays authoritative.
    suite: String,
    root: String,
    length: u64,
}

#[derive(Deserialize)]
pub struct CreateSessionRequest {
    #[serde(default)]
    password: Option<String>,
    package: PackageAnnouncement,
}

fn parse_object(package: &PackageAnnouncement) -> ApiResult<ObjectId> {
    let suite = match package.suite.as_str() {
        "blake3" => Suite::Blake3Bao64,
        "sha256" => Suite::Sha256Bep52,
        other => {
            return Err(ApiError::new(
                StatusCode::UNPROCESSABLE_ENTITY,
                format!("unknown suite {other:?}"),
            ));
        }
    };
    let bytes = hex::decode(&package.root)
        .map_err(|_| ApiError::new(StatusCode::UNPROCESSABLE_ENTITY, "root must be hex"))?;
    let root: [u8; 32] = bytes
        .try_into()
        .map_err(|_| ApiError::new(StatusCode::UNPROCESSABLE_ENTITY, "root must be 32 bytes"))?;
    Ok(ObjectId {
        suite: suite.identifier(),
        root,
        length: package.length,
    })
}

/// Verifies a link password, throttled per client IP: this is the only
/// unauthenticated password check in the service, so without a throttle it
/// would be an oracle, and with a global one anyone holding a link URL could
/// lock the admin out. A link with no password accepts anything.
async fn check_link_password(
    app: &Arc<App>,
    link: &crate::store::Link,
    password: Option<&str>,
    ip: &str,
) -> ApiResult<()> {
    let Some(hash) = &link.password_hash else {
        return Ok(());
    };
    if app.link_throttle.locked(ip) {
        return Err(ApiError::new(
            StatusCode::TOO_MANY_REQUESTS,
            "too many failed attempts; wait a minute",
        ));
    }
    let password = password.unwrap_or_default().to_owned();
    let hash = hash.clone();
    let ok = tokio::task::spawn_blocking(move || auth::verify_password(&password, &hash))
        .await
        .map_err(|error| ApiError::internal(error.to_string()))?;
    app.link_throttle.record(ip, ok);
    if !ok {
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "wrong link password",
        ));
    }
    Ok(())
}

/// Checks a link password without creating any upload state, so the uploader
/// can gate its drop zone behind the password instead of letting someone hash
/// a hundred gigabytes and only then discover they typed it wrong. Success
/// sets a signed cookie so a return visit skips the gate.
pub async fn verify_link_password(
    State(app): State<Arc<App>>,
    Path(token): Path<String>,
    ConnectInfo(peer): ConnectInfo<std::net::SocketAddr>,
    headers: HeaderMap,
    Json(request): Json<VerifyRequest>,
) -> ApiResult<Response> {
    let link = app.store.link(&token).ok_or_else(ApiError::not_found)?;
    if !link.usable_now() {
        return Err(ApiError::new(
            StatusCode::GONE,
            "this link is no longer accepting uploads",
        ));
    }
    let ip = client_ip(&headers, &peer);
    check_link_password(&app, &link, request.password.as_deref(), &ip).await?;
    let phc = link.password_hash.as_deref().unwrap_or_default();
    let value = auth::issue_link_token(&app.secret, &link.id, phc);
    let cookie = format!(
        "{}={value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000{}",
        link_cookie_name(&link.id),
        cookie_attributes(&app)
    );
    Ok(([(header::SET_COOKIE, cookie)], Json(json!({ "ok": true }))).into_response())
}

#[derive(Deserialize)]
pub struct VerifyRequest {
    password: Option<String>,
}

pub async fn create_session(
    State(app): State<Arc<App>>,
    Path(token): Path<String>,
    ConnectInfo(peer): ConnectInfo<std::net::SocketAddr>,
    headers: HeaderMap,
    Json(request): Json<CreateSessionRequest>,
) -> ApiResult<Json<serde_json::Value>> {
    let link = app.store.link(&token).ok_or_else(ApiError::not_found)?;
    if !link.usable_now() {
        return Err(ApiError::new(
            StatusCode::GONE,
            "this link is no longer accepting uploads",
        ));
    }
    if !link_authorized(&app, &link, &headers) {
        let ip = client_ip(&headers, &peer);
        check_link_password(&app, &link, request.password.as_deref(), &ip).await?;
    }
    if app.sessions.active_for_link(&link.id) >= MAX_SESSIONS_PER_LINK
        || app.sessions.total() >= MAX_SESSIONS
    {
        return Err(ApiError::new(
            StatusCode::TOO_MANY_REQUESTS,
            "too many uploads in progress; try again shortly",
        ));
    }
    let expected = parse_object(&request.package)?;
    let cap = effective_cap(&app, &link);
    if expected.length > cap {
        return Err(ApiError::new(
            StatusCode::UNPROCESSABLE_ENTITY,
            format!("upload exceeds the {cap} byte limit for this link"),
        ));
    }
    let dest_components: Vec<String> = link
        .dest
        .split('/')
        .filter(|part| !part.is_empty())
        .map(str::to_owned)
        .collect();
    // admit_dest already vetted these; join_under re-checks as defense.
    let dest_dir =
        paths::join_under(&app.config.receive_dir, &dest_components).map_err(ApiError::internal)?;
    let session_id = auth::random_token();
    let session_bytes: [u8; 16] = hex::decode(&session_id)
        .ok()
        .and_then(|bytes| bytes.try_into().ok())
        .ok_or_else(|| ApiError::internal("session id shape"))?;
    let setup = session::WorkerSetup {
        store: Arc::clone(&app.store),
        link_id: link.id.clone(),
        dest_dir,
        dest_rel: link.dest.clone(),
        expected_package: expected,
        max_total_bytes: cap,
        allow_hidden: app.config.allow_hidden,
        signer: Arc::clone(&app.signer),
        session_id: session_bytes,
        started_at: now_unix(),
    };
    let sender = session::spawn_worker(setup);
    app.sessions.insert(session_id.clone(), link.id, sender);
    Ok(Json(json!({
        "session": session_id,
        "chunk_bytes": session::CHUNK_BYTES,
    })))
}

async fn dispatch<T>(
    app: &App,
    session_id: &str,
    build: impl FnOnce(oneshot::Sender<Result<T, SessionError>>) -> Cmd,
) -> ApiResult<T> {
    let sender = app
        .sessions
        .touch(session_id)
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "unknown or expired session"))?;
    let (reply, receive) = oneshot::channel();
    sender
        .send(build(reply))
        .await
        .map_err(|_| ApiError::new(StatusCode::GONE, "upload session ended"))?;
    receive
        .await
        .map_err(|_| ApiError::new(StatusCode::GONE, "upload session ended"))?
        .map_err(ApiError::from)
}

pub async fn upload_seal(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
    body: Bytes,
) -> ApiResult<Json<serde_json::Value>> {
    if body.len() > session::MAX_SEAL_BYTES {
        return Err(ApiError::new(
            StatusCode::PAYLOAD_TOO_LARGE,
            "seal too large",
        ));
    }
    let pages = dispatch(&app, &sid, |reply| Cmd::Seal { bytes: body, reply }).await?;
    Ok(Json(json!({ "pages": pages })))
}

pub async fn upload_page(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
    body: Bytes,
) -> ApiResult<Json<serde_json::Value>> {
    if body.len() > session::MAX_PAGE_BYTES {
        return Err(ApiError::new(
            StatusCode::PAYLOAD_TOO_LARGE,
            "page too large",
        ));
    }
    let remaining = dispatch(&app, &sid, |reply| Cmd::Page { bytes: body, reply }).await?;
    Ok(Json(json!({ "remaining_pages": remaining })))
}

pub async fn upload_begin(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
) -> ApiResult<Json<serde_json::Value>> {
    let entries = dispatch(&app, &sid, |reply| Cmd::Begin { reply }).await?;
    Ok(Json(json!({ "entries": entries })))
}

#[derive(Deserialize)]
pub struct ChunkQuery {
    entry: usize,
    offset: u64,
}

pub async fn upload_chunk(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
    Query(query): Query<ChunkQuery>,
    headers: HeaderMap,
    body: Bytes,
) -> ApiResult<Json<session::ChunkProgress>> {
    let proof_len: usize = headers
        .get("x-votport-proof")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse().ok())
        .ok_or_else(|| {
            ApiError::new(
                StatusCode::UNPROCESSABLE_ENTITY,
                "X-Votport-Proof header must carry the proof length",
            )
        })?;
    if proof_len > body.len() {
        return Err(ApiError::new(
            StatusCode::UNPROCESSABLE_ENTITY,
            "proof length exceeds the body",
        ));
    }
    // Bytes::slice is a refcount bump, not a copy; the session worker holds
    // the same buffers the request body arrived in.
    let proof = body.slice(..proof_len);
    let data = body.slice(proof_len..);
    let progress = dispatch(&app, &sid, |reply| Cmd::Chunk {
        entry: query.entry,
        offset: query.offset,
        proof,
        data,
        reply,
    })
    .await?;
    Ok(Json(progress))
}

pub async fn upload_finish(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
) -> ApiResult<Json<session::FinishReport>> {
    let link_id = app.sessions.link_id(&sid);
    let report = dispatch(&app, &sid, |reply| Cmd::Finish { reply }).await?;
    app.sessions.remove(&sid);
    if let Some(link) = link_id.and_then(|id| app.store.link(&id)) {
        tokio::spawn(crate::notify::uploaded(
            Arc::clone(&app),
            link.label,
            report.clone(),
        ));
    }
    Ok(Json(report))
}

pub async fn upload_abort(
    State(app): State<Arc<App>>,
    Path(sid): Path<String>,
) -> Json<serde_json::Value> {
    // Best effort: lets the worker record a "cancelled" event; an unknown or
    // already-dead session still answers ok.
    let _ = dispatch(&app, &sid, |reply| Cmd::Abort { reply }).await;
    app.sessions.remove(&sid);
    Json(json!({ "ok": true }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn forwarded_for_is_trusted_only_from_proxy_peers() {
        let mut headers = HeaderMap::new();
        headers.insert("x-forwarded-for", "1.2.3.4, 5.6.7.8".parse().unwrap());
        let proxy: std::net::SocketAddr = "127.0.0.1:80".parse().unwrap();
        let private: std::net::SocketAddr = "172.18.0.2:80".parse().unwrap();
        let public: std::net::SocketAddr = "203.0.113.9:80".parse().unwrap();
        assert_eq!(client_ip(&headers, &proxy), "5.6.7.8");
        assert_eq!(client_ip(&headers, &private), "5.6.7.8");
        assert_eq!(client_ip(&headers, &public), "203.0.113.9");
        assert_eq!(client_ip(&HeaderMap::new(), &proxy), "127.0.0.1");
    }

    #[test]
    fn ipv4_mapped_proxy_peer_is_recognized() {
        let mut headers = HeaderMap::new();
        headers.insert("x-forwarded-for", "9.9.9.9".parse().unwrap());
        // A v4-mapped docker bridge address must still count as a proxy peer;
        // treating it as public would put every sender in one throttle bucket.
        let mapped: std::net::SocketAddr = "[::ffff:172.18.0.2]:80".parse().unwrap();
        assert_eq!(client_ip(&headers, &mapped), "9.9.9.9");
        let mapped_public: std::net::SocketAddr = "[::ffff:203.0.113.9]:80".parse().unwrap();
        // A public mapped peer is not a proxy: its socket address is used and
        // the forwarded header is ignored.
        assert_eq!(client_ip(&headers, &mapped_public), "::ffff:203.0.113.9");
    }
}

//! Environment-driven configuration.

use std::env;
use std::net::SocketAddr;
use std::path::PathBuf;

#[derive(Clone, Debug)]
pub struct Config {
    /// Address the HTTP server binds to.
    pub bind: SocketAddr,
    /// Directory holding votport state (state.json, secret).
    pub data_dir: PathBuf,
    /// Root directory received files are published into.
    pub receive_dir: PathBuf,
    /// Directory holding the static web assets.
    pub web_root: PathBuf,
    /// Argon2 PHC hash of the admin password.
    pub admin_password_hash: String,
    /// Stable tag for the environment-provided admin credential, bound into
    /// session token MACs so rotating the env password (or env hash) evicts
    /// sessions while a plain restart does not. The argon2 hash above cannot
    /// serve: it is salted fresh each boot.
    pub admin_token_tag: String,
    /// Webhook URL POSTed a JSON summary when an upload completes.
    pub notify_webhook: Option<String>,
    /// ntfy topic URL (e.g. "https://ntfy.sh/mytopic") for upload notices.
    pub notify_ntfy: Option<String>,
    /// Bearer token for the ntfy topic, if it needs one.
    pub notify_ntfy_token: Option<String>,
    /// Pushover application token + user key for upload notices.
    pub notify_pushover: Option<(String, String)>,
    /// Public base URL (e.g. "https://drop.example.com"); used to render
    /// links in the admin UI and to decide whether cookies are `Secure`.
    pub public_url: Option<String>,
    /// Hard cap on the total bytes of a single upload session.
    pub max_upload_bytes: u64,
    /// Allow uploaded file names whose components start with a dot.
    pub allow_hidden: bool,
    /// Seconds an upload session may sit idle before it is discarded.
    pub session_idle_secs: u64,
}

const DEFAULT_MAX_UPLOAD_BYTES: u64 = 50 * 1024 * 1024 * 1024; // 50 GiB

pub fn from_env() -> Result<Config, String> {
    let bind = env_or("VOTPORT_BIND", "0.0.0.0:8080")
        .parse()
        .map_err(|error| format!("VOTPORT_BIND is not a socket address: {error}"))?;
    let data_dir = PathBuf::from(env_or("VOTPORT_DATA_DIR", "/data"));
    let receive_dir = PathBuf::from(env_or("VOTPORT_RECEIVE_DIR", "/received"));
    let web_root = PathBuf::from(env_or("VOTPORT_WEB_ROOT", "./web"));

    let (admin_password_hash, admin_token_tag) = match env::var("VOTPORT_ADMIN_PASSWORD_HASH") {
        // The env PHC string is stable across restarts and changes on
        // rotation, so it is its own token tag.
        Ok(hash) if !hash.trim().is_empty() => {
            let hash = hash.trim().to_owned();
            let tag = hash.clone();
            (hash, tag)
        }
        _ => match env::var("VOTPORT_ADMIN_PASSWORD") {
            Ok(password) if !password.is_empty() => {
                use sha2::Digest as _;
                let tag = hex::encode(sha2::Sha256::digest(password.as_bytes()));
                let hash = crate::auth::hash_password(&password)
                    .map_err(|error| format!("failed to hash admin password: {error}"))?;
                (hash, tag)
            }
            _ => {
                return Err(
                    "set VOTPORT_ADMIN_PASSWORD (or VOTPORT_ADMIN_PASSWORD_HASH with an \
                     argon2 PHC string) before starting votport"
                        .to_owned(),
                );
            }
        },
    };

    let public_url = env::var("VOTPORT_PUBLIC_URL")
        .ok()
        .map(|url| url.trim_end_matches('/').to_owned())
        .filter(|url| !url.is_empty());

    let max_upload_bytes = match env::var("VOTPORT_MAX_UPLOAD_BYTES") {
        Ok(value) => {
            parse_bytes(&value).map_err(|error| format!("VOTPORT_MAX_UPLOAD_BYTES: {error}"))?
        }
        Err(_) => DEFAULT_MAX_UPLOAD_BYTES,
    };

    let allow_hidden = env::var("VOTPORT_ALLOW_HIDDEN").is_ok_and(|value| value == "1");

    let session_idle_secs = match env::var("VOTPORT_SESSION_IDLE_SECS") {
        Ok(value) => value
            .parse()
            .map_err(|error| format!("VOTPORT_SESSION_IDLE_SECS: {error}"))?,
        Err(_) => 1800,
    };

    let optional = |name: &str| env::var(name).ok().filter(|value| !value.trim().is_empty());
    let notify_pushover = match (
        optional("VOTPORT_NOTIFY_PUSHOVER_TOKEN"),
        optional("VOTPORT_NOTIFY_PUSHOVER_USER"),
    ) {
        (Some(token), Some(user)) => Some((token, user)),
        (None, None) => None,
        _ => {
            return Err(
                "set both VOTPORT_NOTIFY_PUSHOVER_TOKEN and VOTPORT_NOTIFY_PUSHOVER_USER, \
                 or neither"
                    .to_owned(),
            );
        }
    };

    Ok(Config {
        bind,
        data_dir,
        receive_dir,
        web_root,
        admin_password_hash,
        admin_token_tag,
        notify_webhook: optional("VOTPORT_NOTIFY_WEBHOOK_URL"),
        notify_ntfy: optional("VOTPORT_NOTIFY_NTFY_URL"),
        notify_ntfy_token: optional("VOTPORT_NOTIFY_NTFY_TOKEN"),
        notify_pushover,
        public_url,
        max_upload_bytes,
        allow_hidden,
        session_idle_secs,
    })
}

fn env_or(name: &str, default: &str) -> String {
    env::var(name)
        .ok()
        .filter(|v| !v.is_empty())
        .unwrap_or_else(|| default.to_owned())
}

/// Parses a byte count, optionally suffixed K/KiB/KB, M/MiB/MB, G/GiB/GB or
/// T/TiB/TB (case-insensitive). A bare number stays bytes. All suffix
/// spellings mean x1024^n; the aliases exist so a hand-typed "500G" cannot
/// silently mean 500 bytes or 500000000 by typo.
fn parse_bytes(value: &str) -> Result<u64, String> {
    let trimmed = value.trim();
    let split_at = trimmed
        .char_indices()
        .find(|(_, ch)| !ch.is_ascii_digit())
        .map_or(trimmed.len(), |(idx, _)| idx);
    let (digits, suffix) = trimmed.split_at(split_at);
    let multiplier = match suffix.trim().to_ascii_lowercase().as_str() {
        "" | "b" => 1u64,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024 * 1024 * 1024,
        "t" | "tb" | "tib" => 1024u64 * 1024 * 1024 * 1024,
        other => return Err(format!("unknown size suffix {other:?}")),
    };
    if digits.is_empty() {
        return Err(format!("{value:?} is not a byte count"));
    }
    digits
        .parse::<u64>()
        .map(|bytes| bytes.saturating_mul(multiplier))
        .map_err(|_| format!("{value:?} is out of range"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn byte_counts_accept_suffixes() {
        assert_eq!(parse_bytes("536870912000").unwrap(), 536_870_912_000);
        assert_eq!(parse_bytes("500G").unwrap(), 500 * 1024 * 1024 * 1024);
        assert_eq!(parse_bytes("500GB").unwrap(), 500 * 1024 * 1024 * 1024);
        assert_eq!(parse_bytes("500GiB").unwrap(), 500 * 1024 * 1024 * 1024);
        assert_eq!(parse_bytes("2mib").unwrap(), 2 * 1024 * 1024);
        assert_eq!(parse_bytes("10MB").unwrap(), 10 * 1024 * 1024);
        assert_eq!(
            parse_bytes(" 50T ").unwrap(),
            50 * 1024u64 * 1024 * 1024 * 1024
        );
        assert_eq!(parse_bytes("0").unwrap(), 0);
        assert!(parse_bytes("").is_err());
        assert!(parse_bytes("500x").is_err());
        assert!(parse_bytes("-5").is_err());
        assert!(parse_bytes("G").is_err());
    }
}

//! Application state and router assembly.

use std::sync::Arc;

use axum::extract::DefaultBodyLimit;
use axum::response::{Html, IntoResponse as _};
use axum::routing::{get, post};
use axum::Router;
use tower_http::services::ServeDir;

use crate::api;
use crate::auth::LoginThrottle;
use crate::config::Config;
use crate::session::{self, Sessions};
use crate::store::Store;

pub struct App {
    pub config: Config,
    pub store: Arc<Store>,
    pub sessions: Sessions,
    pub secret: [u8; 32],
    /// Global throttle for the admin password endpoints.
    pub throttle: LoginThrottle,
    /// Per-IP throttle for public link password checks.
    pub link_throttle: crate::auth::IpThrottle,
    /// Signs the `.vot-receipt` sidecars written next to received files.
    pub signer: Arc<crate::receipt::ReceiptSigner>,
    /// Outbound client for upload notifications.
    pub http: reqwest::Client,
}

pub fn build(config: Config) -> Result<Arc<App>, String> {
    // VOT refuses to stage files under a group-writable directory. On hosts
    // with umask 002 (Ubuntu user groups) every directory votport creates
    // would be 0775 and every upload would fail, so pin the umask here.
    #[cfg(unix)]
    rustix::process::umask(rustix::fs::Mode::from_raw_mode(0o022));
    std::fs::create_dir_all(&config.receive_dir)
        .map_err(|error| format!("create {}: {error}", config.receive_dir.display()))?;
    crate::paths::tighten_dir(&config.receive_dir);
    // Staging files from a previous crash or kill have no live session to
    // sweep them; remove them once at startup.
    crate::paths::clean_staging(&config.receive_dir);
    let store = Arc::new(Store::open(&config.data_dir)?);
    let secret = crate::auth::load_secret(&config.data_dir)?;
    let signer = Arc::new(crate::receipt::ReceiptSigner::load_or_create(
        &config.data_dir,
    )?);
    let http = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(15))
        .build()
        .map_err(|error| format!("http client: {error}"))?;
    Ok(Arc::new(App {
        store,
        sessions: Sessions::new(),
        secret,
        throttle: LoginThrottle::new(),
        link_throttle: crate::auth::IpThrottle::new(),
        signer,
        http,
        config,
    }))
}

pub fn router(app: Arc<App>) -> Router {
    let web_root = app.config.web_root.clone();
    let admin_page = web_root.join("index.html");
    let request_page = web_root.join("request.html");

    // Everything the pages load is same-origin (fonts are self-hosted in
    // /assets/fonts). wasm-unsafe-eval is what lets the browser compile the
    // verification engine; there is no JS eval anywhere.
    const CSP: &str = "default-src 'none'; script-src 'self' 'wasm-unsafe-eval'; \
        style-src 'self'; font-src 'self'; connect-src 'self'; \
        img-src 'self' data:; worker-src 'self'; \
        frame-ancestors 'none'; base-uri 'none'; form-action 'self'";
    // Request pages carry the secret link token in the URL; never let the
    // browser forward it as a referrer.
    const REFERRER_POLICY: &str = "no-referrer";

    let serve_page = |path: std::path::PathBuf| {
        get(move || {
            let path = path.clone();
            async move {
                match tokio::fs::read_to_string(&path).await {
                    Ok(contents) => (
                        [
                            (axum::http::header::CONTENT_SECURITY_POLICY, CSP),
                            (axum::http::header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
                            (axum::http::header::REFERRER_POLICY, REFERRER_POLICY),
                            // Same policy as /assets: revalidate every visit so
                            // a redeploy takes effect immediately. Without any
                            // cache header a browser may replay a stale page,
                            // error card and all.
                            (axum::http::header::CACHE_CONTROL, "no-cache"),
                        ],
                        Html(contents),
                    )
                        .into_response(),
                    Err(_) => (
                        axum::http::StatusCode::NOT_FOUND,
                        "page not found; is VOTPORT_WEB_ROOT set correctly?",
                    )
                        .into_response(),
                }
            }
        })
    };

    Router::new()
        // Pages.
        .route("/", serve_page(admin_page))
        .route("/r/{token}", serve_page(request_page))
        // no-cache means revalidate, not never-cache: repeat visits answer
        // conditional GETs with 304s instead of re-downloading the wasm and
        // the hero image, while a redeploy still takes effect immediately.
        .nest_service(
            "/assets",
            tower::ServiceBuilder::new()
                .layer(
                    tower_http::set_header::SetResponseHeaderLayer::if_not_present(
                        axum::http::header::CACHE_CONTROL,
                        axum::http::HeaderValue::from_static("no-cache"),
                    ),
                )
                .layer(tower_http::set_header::SetResponseHeaderLayer::overriding(
                    axum::http::header::REFERRER_POLICY,
                    axum::http::HeaderValue::from_static("no-referrer"),
                ))
                .service(ServeDir::new(web_root.join("assets"))),
        )
        // Admin API.
        .route("/api/admin/login", post(api::admin_login))
        .route("/api/admin/logout", post(api::admin_logout))
        .route("/api/admin/session", get(api::admin_session))
        .route("/api/admin/password", post(api::admin_change_password))
        .route(
            "/api/admin/links",
            get(api::list_links).post(api::create_link),
        )
        .route(
            "/api/admin/links/{id}",
            post(api::update_link).delete(api::delete_link),
        )
        .route("/api/admin/links/{id}/qr", get(api::link_qr))
        .route(
            "/api/admin/links/{id}/uploads/{upload}",
            axum::routing::delete(api::delete_upload_record),
        )
        .route(
            "/api/admin/links/{id}/uploads/{upload}/files/{index}",
            axum::routing::delete(api::delete_received_file),
        )
        // Public upload API.
        .route("/api/r/{token}", get(api::link_info))
        .route("/api/r/{token}/verify", post(api::verify_link_password))
        .route("/api/r/{token}/session", post(api::create_session))
        .route(
            "/api/session/{sid}/seal",
            post(api::upload_seal).layer(DefaultBodyLimit::max(session::MAX_SEAL_BYTES + 1024)),
        )
        .route(
            "/api/session/{sid}/page",
            post(api::upload_page).layer(DefaultBodyLimit::max(session::MAX_PAGE_BYTES + 1024)),
        )
        .route("/api/session/{sid}/begin", post(api::upload_begin))
        .route(
            "/api/session/{sid}/chunk",
            post(api::upload_chunk).layer(DefaultBodyLimit::max(session::MAX_CHUNK_BODY_BYTES)),
        )
        .route("/api/session/{sid}/finish", post(api::upload_finish))
        .route("/api/session/{sid}/abort", post(api::upload_abort))
        .layer(DefaultBodyLimit::max(64 * 1024))
        .with_state(app)
}

/// Discards idle upload sessions so abandoned staging files get cleaned up.
pub async fn session_sweeper(app: Arc<App>) {
    let idle = app.config.session_idle_secs;
    loop {
        tokio::time::sleep(std::time::Duration::from_secs(60)).await;
        app.sessions.sweep(idle);
    }
}

//! Signed VOT assurance receipts written as sidecars next to received files.
//!
//! Each published file gets `<name>.vot-receipt`: a canonical vot-receipt
//! CBOR envelope, ed25519-signed with a key generated in the data directory,
//! attesting that this exact object (suite, root, length) reached Published
//! assurance under the Balanced commit profile. The key id is the 32-byte
//! public key itself, so a receipt is verifiable against the key the admin
//! page displays with nothing else.

use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use ed25519_dalek::SigningKey;
use vot_receipt::{
    encode_authenticated, required_predecessor, sign_ed25519, AssuranceLevel, CommitProfile,
    Receipt, SubjectKind,
};
use vot_sdk::object::ObjectId;
use vot_sdk_file::PublishObservation;

/// votport's provider version in issued receipts.
const PROVIDER_VERSION: [u16; 3] = [0, 1, 0];
/// POSIX_LOCAL in spec/registries.yaml.
const PROVIDER: u16 = 1;

pub struct ReceiptSigner {
    key: SigningKey,
    /// Hex of the ed25519 public key; shown in the admin UI for verification.
    pub public_hex: String,
}

impl ReceiptSigner {
    /// Loads or creates the 32-byte signing seed in the data directory.
    pub fn load_or_create(data_dir: &Path) -> Result<Self, String> {
        let path = data_dir.join("receipt.key");
        let seed: [u8; 32] = match std::fs::read(&path) {
            Ok(bytes) => bytes
                .try_into()
                .map_err(|_| format!("{} is not a 32-byte key seed", path.display()))?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                let mut seed = [0u8; 32];
                use rand::RngCore as _;
                rand::rngs::OsRng.fill_bytes(&mut seed);
                crate::auth::write_private(&path, &seed).map_err(|error| error.to_string())?;
                seed
            }
            Err(error) => return Err(format!("read {}: {error}", path.display())),
        };
        let key = SigningKey::from_bytes(&seed);
        let public_hex = hex::encode(key.verifying_key().to_bytes());
        Ok(Self { key, public_hex })
    }

    /// Writes `<destination>.vot-receipt` attesting the published object.
    pub fn write_sidecar(
        &self,
        destination: &Path,
        object: &ObjectId,
        session_id: [u8; 16],
        observation: PublishObservation,
    ) -> Result<PathBuf, String> {
        let receipt = Receipt {
            subject_kind: SubjectKind::Object,
            suite_id: object.suite,
            subject_digest: object.root,
            subject_length: object.length,
            assurance: AssuranceLevel::Published,
            profile: CommitProfile::Balanced,
            actual_predecessor: required_predecessor(CommitProfile::Balanced),
            provider: PROVIDER,
            provider_version: PROVIDER_VERSION,
            session_id,
            incarnation_id: observation.incarnation,
            sequence: observation.sequence,
            observed_at: rfc3339_now(),
            // 1 = system UTC, matching the canonical vot-receipt vectors.
            clock_source: 1,
            flags: 0,
            // ponytail: no chain; each receipt stands alone. Link `previous`
            // if a subject is ever observed more than once.
            previous: None,
        };
        let key_id = self.key.verifying_key().to_bytes();
        let authenticated = sign_ed25519(receipt, &key_id, &self.key)
            .map_err(|error| format!("sign receipt: {error:?}"))?;
        let bytes = encode_authenticated(&authenticated)
            .map_err(|error| format!("encode receipt: {error:?}"))?;
        let mut sidecar = destination.as_os_str().to_owned();
        sidecar.push(".vot-receipt");
        let sidecar = PathBuf::from(sidecar);
        std::fs::write(&sidecar, bytes)
            .map_err(|error| format!("write {}: {error}", sidecar.display()))?;
        Ok(sidecar)
    }
}

/// RFC 3339 UTC seconds from the system clock, e.g. "2026-08-20T04:05:06Z".
fn rfc3339_now() -> String {
    rfc3339(
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |duration| duration.as_secs()),
    )
}

fn rfc3339(unix: u64) -> String {
    let days = i64::try_from(unix / 86_400).unwrap_or(0);
    let seconds = unix % 86_400;
    // Civil-from-days (Howard Hinnant's algorithm), valid for the era range
    // a running server can observe.
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { year + 1 } else { year };
    format!(
        "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}Z",
        seconds / 3600,
        (seconds % 3600) / 60,
        seconds % 60
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rfc3339_matches_known_timestamps() {
        assert_eq!(rfc3339(0), "1970-01-01T00:00:00Z");
        assert_eq!(rfc3339(951_782_400), "2000-02-29T00:00:00Z");
        assert_eq!(rfc3339(1_755_662_400), "2025-08-20T04:00:00Z");
        assert_eq!(rfc3339(4_102_444_799), "2099-12-31T23:59:59Z");
    }

    #[test]
    fn sidecar_receipt_round_trips_and_verifies() {
        let directory = tempfile::tempdir().unwrap();
        let signer = ReceiptSigner::load_or_create(directory.path()).unwrap();
        let reloaded = ReceiptSigner::load_or_create(directory.path()).unwrap();
        assert_eq!(signer.public_hex, reloaded.public_hex, "key is persistent");

        let destination = directory.path().join("payload.bin");
        let object = ObjectId {
            suite: 1,
            root: [9; 32],
            length: 4096,
        };
        let sidecar = signer
            .write_sidecar(
                &destination,
                &object,
                [2; 16],
                PublishObservation {
                    incarnation: [3; 16],
                    sequence: 7,
                },
            )
            .unwrap();
        assert_eq!(sidecar, directory.path().join("payload.bin.vot-receipt"));

        let bytes = std::fs::read(&sidecar).unwrap();
        let decoded = vot_receipt::decode_authenticated(&bytes).unwrap();
        let key = ed25519_dalek::VerifyingKey::from_bytes(
            &hex::decode(&signer.public_hex).unwrap().try_into().unwrap(),
        )
        .unwrap();
        let verified = vot_receipt::verify_ed25519(&decoded, &key).unwrap();
        assert_eq!(verified.receipt().subject_digest, [9; 32]);
        assert_eq!(verified.receipt().sequence, 7);
    }
}

