use votport::{app, config};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        // RUST_LOG wins; info is the right default for a deployed server.
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();
    let config = match config::from_env() {
        Ok(config) => config,
        Err(error) => {
            eprintln!("votport: {error}");
            std::process::exit(2);
        }
    };
    let bind = config.bind;
    let application = match app::build(config) {
        Ok(application) => application,
        Err(error) => {
            tracing::error!("{error}");
            std::process::exit(2);
        }
    };
    tokio::spawn(app::session_sweeper(application.clone()));
    let router = app::router(application.clone());
    let listener = match tokio::net::TcpListener::bind(bind).await {
        Ok(listener) => listener,
        Err(error) => {
            tracing::error!("bind {bind}: {error}");
            std::process::exit(2);
        }
    };
    tracing::info!(
        "votport listening on {bind}; receiving into {}",
        application.config.receive_dir.display()
    );
    // ConnectInfo carries the peer address to the per-IP link throttle.
    if let Err(error) = axum::serve(
        listener,
        router.into_make_service_with_connect_info::<std::net::SocketAddr>(),
    )
    .with_graceful_shutdown(shutdown_signal())
    .await
    {
        tracing::error!("server error: {error}");
        std::process::exit(1);
    }
}

async fn shutdown_signal() {
    // Docker and systemd stop the process with SIGTERM; ctrl_c is SIGINT
    // only. Without this a container stop skips graceful shutdown entirely.
    let ctrl_c = async {
        let _ = tokio::signal::ctrl_c().await;
    };
    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        signal(SignalKind::terminate())
            .expect("install SIGTERM handler")
            .recv()
            .await;
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
    tracing::info!("shutting down");
}

//! Upload-completion notifications: webhook, ntfy, Pushover.
//!
//! Best-effort and fire-and-forget: a completed transfer is already recorded
//! and on disk, so a notification failure is logged and nothing else.

use std::sync::Arc;

use serde_json::json;

use crate::app::App;
use crate::session::FinishReport;

/// Sends every configured notification for one completed upload.
pub async fn uploaded(app: Arc<App>, label: String, report: FinishReport) {
    let total: u64 = report.files.iter().map(|file| file.bytes).sum();
    let count = report.files.len();
    let title = format!("votport: files received for \"{label}\"");
    let body = format!(
        "{count} file(s), {total} bytes\n{}",
        report
            .files
            .iter()
            .map(|file| format!("{} ({} bytes)", file.stored_as, file.bytes))
            .collect::<Vec<_>>()
            .join("\n")
    );

    if let Some(url) = &app.config.notify_webhook {
        let payload = json!({
            "event": "upload_complete",
            "label": label,
            "upload_id": report.upload_id,
            "total_bytes": total,
            "files": report.files,
        });
        log_failure("webhook", app.http.post(url).json(&payload).send().await);
    }

    if let Some(url) = &app.config.notify_ntfy {
        let mut request = app
            .http
            .post(url)
            .header("Title", title.clone())
            .body(body.clone());
        if let Some(token) = &app.config.notify_ntfy_token {
            request = request.bearer_auth(token);
        }
        log_failure("ntfy", request.send().await);
    }

    if let Some((token, user)) = &app.config.notify_pushover {
        let request = app
            .http
            .post("https://api.pushover.net/1/messages.json")
            .form(&[
                ("token", token.as_str()),
                ("user", user.as_str()),
                ("title", title.as_str()),
                ("message", body.as_str()),
            ]);
        log_failure("pushover", request.send().await);
    }
}

fn log_failure(target: &str, result: Result<reqwest::Response, reqwest::Error>) {
    match result {
        Ok(response) if !response.status().is_success() => {
            tracing::warn!(target, status = %response.status(), "notification failed");
        }
        Err(error) => tracing::warn!(target, "notification failed: {error}"),
        Ok(_) => {}
    }
}

